import{_ as e,C as r,o,c as n,a2 as t,E as d}from"./chunks/framework.BqNd1sPY.js";const g=JSON.parse('{"title":"D06：拼出完整 Transformer","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D06-拼出完整Transformer.md","filePath":"01-14天理论课/D06-拼出完整Transformer.md"}'),m={name:"01-14天理论课/D06-拼出完整Transformer.md"};function s(c,a,l,k,w,u){const i=r("MermaidDiagram");return o(),n("div",null,[a[0]||(a[0]=t('<h1 id="d06-拼出完整-transformer" tabindex="-1">D06：拼出完整 Transformer <a class="header-anchor" href="#d06-拼出完整-transformer" aria-label="Permalink to &quot;D06：拼出完整 Transformer&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>能画出 Decoder-only <a href="/LLMTrain/05-速查表/术语速查#term-transformer" class="wiki-term" data-wiki-title="Transformer" data-wiki-summary="由注意力、MLP、残差连接和归一化等模块组成的一类神经网络架构。" data-wiki-misconception="所有大模型都只能采用同一种 Transformer 结构。">Transformer</a> 的主要数据流，并解释残差连接、归一化和 MLP 的作用。</p><h2 id="一个现代-decoder-的教学骨架" tabindex="-1">一个现代 Decoder 的教学骨架 <a class="header-anchor" href="#一个现代-decoder-的教学骨架" aria-label="Permalink to &quot;一个现代 Decoder 的教学骨架&quot;">​</a></h2>',4)),d(i,{code:""}),a[1]||(a[1]=t('<p>具体模型会改变 Norm 的类型和位置、位置编码、激活函数、是否使用 <a href="/LLMTrain/05-速查表/术语速查#term-moe" class="wiki-term" data-wiki-title="MoE" data-wiki-summary="通过路由让每个 token 只激活部分专家子网络的架构。" data-wiki-misconception="多个完整模型对同一答案投票。">MoE</a>、是否共享输入输出权重等。上图是理解主干，不是所有模型的逐层施工图。</p><h2 id="每个零件在做什么" tabindex="-1">每个零件在做什么 <a class="header-anchor" href="#每个零件在做什么" aria-label="Permalink to &quot;每个零件在做什么&quot;">​</a></h2><ul><li><strong><a href="/LLMTrain/05-速查表/术语速查#term-embedding" class="wiki-term" data-wiki-title="embedding" data-wiki-summary="把离散 ID 映射为连续向量的可训练表示。" data-wiki-misconception="embedding 是人工指定的固定语义坐标。">Embedding</a></strong>：把 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> ID 查成向量。</li><li><strong><a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a></strong>：让当前位置按计算权重汇入此前位置的信息。</li><li><strong>MLP/FFN</strong>：对每个位置分别做非线性变换，扩展表示能力。</li><li><strong>残差连接</strong>：把子层输入直接加回输出，为信息和<a href="/LLMTrain/05-速查表/术语速查#term-gradient" class="wiki-term" data-wiki-title="gradient" data-wiki-summary="loss 对各参数的局部变化率，指出当前附近怎样调整会改变 loss。" data-wiki-misconception="梯度直接给出了全局最优答案。">梯度</a>提供短路径。</li><li><strong>归一化</strong>：控制表示尺度，改善训练稳定性。LayerNorm 与 RMSNorm 计算不同，不能简单说后者只是“更快版”而忽略架构<a href="/LLMTrain/05-速查表/术语速查#term-context" class="wiki-term" data-wiki-title="context" data-wiki-summary="模型本次计算能够看到的 token 序列。" data-wiki-misconception="放进上下文的信息已经永久写入模型参数。">上下文</a>。</li><li><strong>LM Head</strong>：把隐藏向量映射成<a href="/LLMTrain/05-速查表/术语速查#term-vocab" class="wiki-term" data-wiki-title="vocab" data-wiki-summary="tokenizer 可以表示的 token 集合；输出层通常也对这组 token 给出分数。" data-wiki-misconception="词表包含了模型掌握的全部知识。">词表</a>中每个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 的 <a href="/LLMTrain/05-速查表/术语速查#term-logits" class="wiki-term" data-wiki-title="logits" data-wiki-summary="softmax 之前的任意实数分数，用来比较各候选 token。" data-wiki-misconception="logits 已经是概率或正确率。">logits</a>。</li></ul><h2 id="encoder、decoder-与-encoder-decoder" tabindex="-1">Encoder、Decoder 与 Encoder-Decoder <a class="header-anchor" href="#encoder、decoder-与-encoder-decoder" aria-label="Permalink to &quot;Encoder、Decoder 与 Encoder-Decoder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>典型<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a></th><th>常见用途</th></tr></thead><tbody><tr><td>Encoder-only</td><td>双向自<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a></td><td>表示、分类、抽取</td></tr><tr><td>Decoder-only</td><td>因果自<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a></td><td>自回归生成，现代 LLM 主流</td></tr><tr><td>Encoder-Decoder</td><td>编码器双向，解码器因果并含交叉<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a></td><td>翻译、条件生成</td></tr></tbody></table><p>“主流”不等于其他架构无用。还存在 RNN、状态空间模型和混合架构，它们在不同约束下有价值。</p><h2 id="参数量在哪里" tabindex="-1">参数量在哪里 <a class="header-anchor" href="#参数量在哪里" aria-label="Permalink to &quot;参数量在哪里&quot;">​</a></h2><p><a href="/LLMTrain/05-速查表/术语速查#term-embedding" class="wiki-term" data-wiki-title="embedding" data-wiki-summary="把离散 ID 映射为连续向量的可训练表示。" data-wiki-misconception="embedding 是人工指定的固定语义坐标。">Embedding</a>、<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a>投影、MLP 和输出层都可能包含<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>。序列长度主要影响本次计算和激活内存，不直接增加已训练模型的<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>个数。</p><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><p>闭卷画出：<code>token -&gt; embedding -&gt; N 个 Block -&gt; logits</code>，并在 Block 中标出<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a>、MLP、Norm、残差和<a href="/LLMTrain/05-速查表/术语速查#term-causal-mask" class="wiki-term" data-wiki-title="causal mask" data-wiki-summary="在自回归训练中阻止当前位置读取未来 token 的遮罩。" data-wiki-misconception="它会阻止模型读取当前位置之前的内容。">因果遮罩</a>。</p><p>再回答：为什么没有 MLP 的纯<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a>堆叠表达会受限？为什么残差连接不是“把错误也加回来”这么简单？</p><p>下一课：<a href="./D07-模型如何生成文字">D07：模型如何生成文字</a></p>',12))])}const L=e(m,[["render",s]]);export{g as __pageData,L as default};
